using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;
public sealed class SkillReworkTests:MonoBehaviour {
 public static bool MotionOnly;public static bool LobOnly;public static bool TempoOnly;public static bool PreviewOnly;public static int lobChoice;static int groundContacts;static string blocker;static bool blocked;static bool equalChance=true;
 public static bool WantLob(float chance){equalChance &= Mathf.Abs(chance-.5f)<.0001f;return lobChoice>0;}
 public static int lobs;static float floorLimit;
 public static void Lobbed(Component actor){lobs++;}
 public static void WorldContact(Collision2D c){Component a=c.collider.GetComponentInParent<BuildPlayer>();Component d=c.otherCollider.GetComponentInParent<BuildPlayer>();if((a!=null&&a.name==blocker)||(d!=null&&d.name==blocker))blocked=true;if(a==null&&d==null)for(int i=0;i<c.contactCount;i++)if(c.GetContact(i).point.y<floorLimit+.08f){groundContacts++;break;}}
 public static bool UseAI;static bool booted;static HashSet<KeyCode> keys=new HashSet<KeyCode>();static Dictionary<KeyCode,int> frames=new Dictionary<KeyCode,int>();
 public static bool ReadKey(KeyCode k){return keys.Contains(k);}public static bool ReadDown(KeyCode k){if(!keys.Contains(k))return false;int f;if(!frames.TryGetValue(k,out f)){frames[k]=Time.frameCount;return true;}return f==Time.frameCount;}
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","cannon-test.ini");var o=new GameObject("SkillReworkTests");DontDestroyOnLoad(o);o.AddComponent<SkillReworkTests>();}
 static Dictionary<string,Vector2> shots=new Dictionary<string,Vector2>(),inputs=new Dictionary<string,Vector2>();public static void Launched(Component p,Vector2 velocity,Vector2 incoming){shots[p.name]=velocity;inputs[p.name]=incoming;}
 Type pt;Component fan,zhao,manager;Rigidbody2D ball;float scale;int checks,failures;const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic,IP=BindingFlags.Instance|BindingFlags.NonPublic;
 void Check(bool pass,string text){checks++;if(!pass)failures++;Debug.Log("ABILITY "+(pass?"PASS ":"FAIL ")+text);}
 Rigidbody2D Body(Component p){return (Rigidbody2D)pt.GetField("rb").GetValue(p);}
 void Move(Component p,Vector2 at){p.transform.position+=(Vector3)(at-Body(p).position);foreach(var b in p.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
 float Error(Component p){float e=0;foreach(var j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)e=Mathf.Max(e,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return e;}
 int[] Levels(int total,bool alternate=false){switch(total){case 0:return new int[]{0,0,0};case 8:return new int[]{3,3,2};case 11:return new int[]{4,4,3};case 12:return alternate?new int[]{8,4,0}:new int[]{4,4,4};case 13:return new int[]{5,4,4};case 14:return new int[]{6,4,4};case 16:return new int[]{8,4,4};default:return new int[]{8,8,6};}}
 IEnumerator Scene(int total,int mode=2,bool cannon=true,bool alternate=false){AbilityMode.SetBudget(24);keys.Clear();frames.Clear();shots.Clear();inputs.Clear();lobChoice=groundContacts=lobs=0;blocker=null;blocked=false;UseAI=false;Time.timeScale=1;ControlBindings.ResetDefaults();AbilityMode.Reset();AbilityMode.Enabled=mode==2;PlayerSkills.Enabled=mode==1;int[] levels=Levels(total,alternate);foreach(var b in AbilityMode.Builds){for(int i=0;i<3;i++)b.Levels[i]=levels[i];b.Purchased=cannon?1<<1:0;}UnityEngine.Random.InitState(981);typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.4f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();floorLimit=GameObject.Find("Down").GetComponent<Collider2D>().bounds.max.y;scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;ball.position=new Vector2(0,4*scale);ball.velocity=Vector2.zero;ball.gravityScale=0;foreach(var a in FindObjectsOfType<Animator>())a.cullingMode=AnimatorCullingMode.AlwaysAnimate;GameAIMod.OnBallReset();yield return new WaitForSeconds(.1f);}
 void Setup(Component actor){float dir=actor.name=="Fan"?1:-1;Move(actor,new Vector2(0,Body(actor).position.y));Move(actor==fan?zhao:fan,new Vector2(-dir*4.2f*scale,Body(actor==fan?zhao:fan).position.y));}
 void ContactBall(Component actor,bool rear=false){Vector2 facing=PowerShot.HeadFacing(actor);Collider2D shape=actor.transform.Find("Head").GetComponent<Collider2D>();Vector2 edge=shape.ClosestPoint((Vector2)shape.bounds.center+facing*(rear?-3:3));ball.position=edge+facing*(rear?-1:1)*(ball.GetComponent<Collider2D>().bounds.extents.x-.012f*scale);ball.velocity=facing*(rear?1:-1)*.8f;ball.gravityScale=1;Physics2D.SyncTransforms();}
 void Head(Component actor){PlayerSkills.SetAction((Animator)pt.GetField("anim").GetValue(actor),"Head",actor);}
 void Lean(Component actor,float angle){Vector2 center=Body(actor).position;float c=Mathf.Cos(angle*Mathf.Deg2Rad),s=Mathf.Sin(angle*Mathf.Deg2Rad);foreach(var limb in actor.GetComponentsInChildren<Rigidbody2D>()){Vector2 o=limb.position-center;limb.position=center+new Vector2(o.x*c-o.y*s,o.x*s+o.y*c);limb.rotation+=angle;limb.velocity=Vector2.zero;limb.angularVelocity=0;}Physics2D.SyncTransforms();}

 static int forgiven,bicycles;static Component lastShooter;static bool wasBicycle;static int lastQuality;static Vector2 lastShot;public static void Forgiven(Component p,bool bicycle,int quality,Vector2 velocity){forgiven++;lastShooter=p;wasBicycle=bicycle;lastQuality=quality;lastShot=velocity;}public static void Started(){bicycles++;}
 void Action(Component p,string action){PlayerSkills.SetAction((Animator)pt.GetField("anim").GetValue(p),action,p);}
 void SeedSuccess(){for(int seed=0;seed<100;seed++){UnityEngine.Random.InitState(seed);if(UnityEngine.Random.value<.5f){UnityEngine.Random.InitState(seed);return;}}}
 object Field(Component p,string name){return typeof(SkillRework).GetField(name,IP).GetValue(p.GetComponent<SkillRework>());}
 void Write(Component p,string name,object value){typeof(SkillRework).GetField(name,IP).SetValue(p.GetComponent<SkillRework>(),value);}
 void CaptureActual(Component actor,string frame=null){var c=Camera.main;var rt=new RenderTexture(1280,720,24);var old=c.targetTexture;var active=RenderTexture.active;c.targetTexture=rt;c.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();System.IO.File.WriteAllBytes(System.IO.Path.Combine(Application.dataPath,"..",frame??(actor.name=="Fan"?"倒挂金钩特写.png":"赵鹏倒挂金钩特写.png")),image.EncodeToPNG());Debug.Log("CAMERA_CAPTURE pos="+c.transform.position+" size="+c.orthographicSize+" actor="+Body(actor).position+" angle="+Body(actor).rotation);c.targetTexture=old;RenderTexture.active=active;Destroy(image);Destroy(rt);}
 IEnumerator Preview(bool isFan){yield return Scene(12);var actor=isFan?fan:zhao;Setup(actor);AbilityMode.For(actor).Purchased=1<<10;var body=Body(actor);ball.position=body.position+new Vector2((isFan?-1:1)*.48f*scale,.52f*scale);ball.velocity=Vector2.zero;ball.gravityScale=0;Physics2D.SyncTransforms();SeedSuccess();int before=bicycles;pt.GetField("doJump").SetValue(actor,true);Action(actor,"Jump");Action(actor,"Kick");float nativeSpeed=1f;bool mirrored=actor.transform.localScale.x<0,half=false,zoom=false;float error=0;float began=Time.realtimeSinceStartup;bool captured=false;while(Time.realtimeSinceStartup-began<1.1f){yield return null;half|=Mathf.Abs(Time.timeScale-.5f)<.01f;zoom|=Camera.main!=null&&Camera.main.orthographicSize<3f;error=Mathf.Max(error,Error(actor));if(Time.frameCount%10==0)Debug.Log("BICYCLE_TRACE actor="+actor.name+" t="+(Time.time-(float)Field(actor,"started"))+" rb="+body.rotation+" up="+body.transform.TransformVector(Vector3.up)+" head="+actor.transform.Find("Head").position+" hip="+body.position+" foot="+actor.transform.Find("L_LowLeg").position+" ball="+ball.position);if(!captured&&Time.realtimeSinceStartup-began>.48f){yield return new WaitForEndOfFrame();CaptureActual(actor);captured=true;Debug.Log("PREVIEW_CAPTURE saved closeup");}}
 Check(bicycles>before&&half&&zoom&&error<.65f&&mirrored,"whole model mirrors before 0.5x bicycle actor="+actor.name+" joints="+error+" starts="+(bicycles-before));ShotCloseup.End(actor);yield return null;Check(Mathf.Abs(Time.timeScale-nativeSpeed)<.01f&&!ShotCloseup.Active,"closeup restores normal camera and speed");bool held=true;for(int i=0;i<180;i++){yield return new WaitForFixedUpdate();bool turned=(bool)Field(actor,"turned");if(turned&&(!(bool)pt.GetField("isOnGround").GetValue(actor)||Mathf.Abs(Mathf.DeltaAngle(Body(actor).rotation,0))>20))held&=actor.transform.localScale.x<0;if(!turned)break;}Check(held&&actor.transform.localScale.x>0&&!(bool)Field(actor,"turned"),"mirror persists through landing and restores after standing actor="+actor.name+" angle="+Body(actor).rotation);}
 IEnumerator Motion(bool isFan,float height,float offset){
 yield return Scene(12);var a=isFan?fan:zhao;Setup(a);AbilityMode.For(a).Purchased=1<<10;var rb=Body(a);float dir=isFan?1:-1;float x0=rb.position.x;
 ball.position=rb.position+new Vector2(-dir*offset*scale,height*scale);ball.velocity=Vector2.zero;ball.gravityScale=1;Physics2D.SyncTransforms();SeedSuccess();int before=forgiven,starts=bicycles;
 Action(a,"Jump");Action(a,"Kick");bool mirror=a.transform.localScale.x<0;bool backTurn=false,frontTurn=false,landed=false,getup=false,held=true,hit=false,half=false;float error=0;float began=Time.time;int image=0,frameIndex=0;float nextFrame=0f;float minAngle=0,maxAngle=0;
 string trace=System.IO.Path.Combine(Application.dataPath,"..","motion-"+a.name+"-"+height+"-"+offset+".csv");var writer=new System.IO.StreamWriter(trace);writer.WriteLine("time,angle,x,y,foot_x,foot_y,ball_x,ball_y,landed,getup,mirrored,shot");
 for(int i=0;i<200;i++){yield return new WaitForFixedUpdate();float t=Time.time-began;float angle=Mathf.DeltaAngle(0,rb.rotation)*dir;minAngle=Mathf.Min(minAngle,angle);maxAngle=Mathf.Max(maxAngle,angle);backTurn|=angle<-65;frontTurn|=angle>65;landed|=(float)Field(a,"landedAt")>=0;getup|=(float)Field(a,"getupAt")>=0;bool turned=(bool)Field(a,"turned");half|=Mathf.Abs(Time.timeScale-.5f)<.01f;error=Mathf.Max(error,Error(a));if(forgiven>before&&lastShooter==a&&wasBicycle)hit=lastShot.x*dir>0;
 if(turned&&(!landed||!(bool)pt.GetField("isOnGround").GetValue(a)||Mathf.Abs(Mathf.DeltaAngle(rb.rotation,0))>20))held&=a.transform.localScale.x<0;
 Vector2 foot=a.transform.Find("L_LowLeg").position;writer.WriteLine(t+","+angle+","+rb.position.x+","+rb.position.y+","+foot.x+","+foot.y+","+ball.position.x+","+ball.position.y+","+landed+","+getup+","+turned+","+hit);
 if(height==.7f&&offset==.4f&&t>=nextFrame){yield return new WaitForEndOfFrame();CaptureActual(a,"motionframe-"+a.name+"-"+(frameIndex++).ToString("D3")+".png");nextFrame=t+.06f;}
 if(height==.7f&&offset==.4f&&image==0&&angle<-60){yield return new WaitForEndOfFrame();CaptureActual(a);image++;}
 if(!turned&&t>.6f)break;if(t>3.9f)break;}
 writer.Dispose();Check(bicycles>starts&&mirror&&half,"mirrored windup and half speed actor="+a.name+" height="+height);
 Check(backTurn&&!frontTurn,"backward half somersault direction actor="+a.name+" min="+minAngle+" max="+maxAngle);
 Check(hit,"actual boot collision shoots toward opposing goal actor="+a.name+" height="+height+" offset="+offset+" contacts="+(forgiven-before));
 Check(landed&&getup&&held&&a.transform.localScale.x>0&&!(bool)Field(a,"turned")&&Mathf.Abs(Mathf.DeltaAngle(rb.rotation,0))<20,"back landing then quick getup before turn actor="+a.name+" landed="+landed+" getup="+getup+" angle="+rb.rotation);
 Check(error<.75f,"connected rig stays smooth actor="+a.name+" error="+error);ShotCloseup.End(a);
 }
 void Rules(){AbilityMode.SetBudget(24);AbilityMode.Reset();var b=AbilityMode.Builds[0];Check(AbilityMode.Skills.Length==11&&AbilityMode.Skills[4]=="后方领袖"&&b.Toggle(10)&&b.Used==14&&b.Valid,"new skill shop, cost two and replacement");int[] quality=new int[3];for(int i=0;i<100;i++)quality[SkillRework.Quality((i+.5f)/100f)]++;Check(quality[0]==70&&quality[1]==20&&quality[2]==10,"bicycle quality bands 70/20/10");Check(PlayerSkills.TackleKnockbackBodyWidths==1f,"power tackle limits baseline displacement to one body");}
 IEnumerator Passives(bool isFan){yield return Scene(12);var a=isFan?fan:zhao;Setup(a);AbilityMode.Builds[isFan?0:1].Purchased=1<<4;int raw=AbilityMode.For(a).Levels[1];float tied=SkillRework.Effective(a,1);manager.GetType().GetField(isFan?"p2Score":"p1Score").SetValue(manager,1);float losing=SkillRework.Effective(a,1);Check(tied==5.5f&&losing==4&&AbilityMode.For(a).Levels[1]==raw,"rear leader +1.5 only while tied/leading actor="+a.name);manager.GetType().GetField(isFan?"p2Score":"p1Score").SetValue(manager,0);AbilityMode.For(a).Purchased=1<<2;var o=isFan?zhao:fan;Move(a,new Vector2(0,Body(a).position.y+1.6f*scale));Move(o,new Vector2((isFan?1:-1)*.55f*scale,Body(a).position.y));pt.GetField("isOnGround").SetValue(a,false);pt.GetField("isOnGround").SetValue(o,false);ball.position=Body(a).position+Vector2.up*1f*scale;Physics2D.SyncTransforms();float combat=SkillRework.Effective(a,1),jump=SkillRework.Effective(a,2);Move(o,new Vector2(4*scale,Body(o).position.y));Check(combat==5&&jump==5&&SkillRework.Effective(a,1)==4,"fortress +1 contest/jump only in close aerial duel actor="+a.name);}
 IEnumerator Header(bool isFan,int mode,bool crown,bool rear){yield return Scene(12,mode);var a=isFan?fan:zhao;Setup(a);if(crown){var h=a.transform.Find("Head").GetComponent<Collider2D>();ball.position=new Vector2(h.bounds.center.x,h.bounds.max.y+ball.GetComponent<Collider2D>().bounds.extents.y-.012f*scale);ball.velocity=Vector2.down*.5f;ball.gravityScale=1;Physics2D.SyncTransforms();}else ContactBall(a,rear);Action(a,"Kick");for(int i=0;i<16;i++)yield return new WaitForFixedUpdate();bool fired=shots.ContainsKey(a.name);Check(rear?!fired:fired,"kick arms real face/crown cannon but never rear actor="+a.name+" mode="+mode+" crown="+crown+" rear="+rear+" fired="+fired);}
 IEnumerator Fallback(bool isFan,int part){yield return Scene(12);var a=isFan?fan:zhao;Setup(a);AbilityMode.For(a).Purchased=1<<10;var limb=a.transform.Find(part==0?"L_Up_Leg":"L_LowLeg").GetComponent<Collider2D>();Vector2 n=part==0?Vector2.right*(isFan?1:-1):Vector2.down;Vector2 edge=limb.ClosestPoint((Vector2)limb.bounds.center+n*3);ball.position=edge+n*(ball.GetComponent<Collider2D>().bounds.extents.x-.015f*scale);ball.velocity=-n;ball.gravityScale=1;Physics2D.SyncTransforms();int before=forgiven;Action(a,"Kick");for(int i=0;i<18;i++)yield return new WaitForFixedUpdate();Check(forgiven>before&&lastQuality==-1&&lastShot.magnitude>3,"actual awkward lower-body contact triggers 90 percent shot actor="+a.name+" thigh="+(part==0)+" fired="+(forgiven-before));}
 IEnumerator Knocked(bool isFan){yield return Scene(12);var a=isFan?fan:zhao;Setup(a);SkillRework.Tackled(a);Check((bool)typeof(SkillRework).GetMethod("AwkwardPose",IP).Invoke(a.GetComponent<SkillRework>(),null),"post power-tackle shot qualifies actor="+a.name);}
 IEnumerator Magnetic(bool isFan){yield return Scene(12);var a=isFan?fan:zhao;Setup(a);AbilityMode.For(a).Purchased=1<<8;var hip=a.transform.Find("L_Up_Leg").GetComponent<HingeJoint2D>();Vector2 at=hip.connectedBody.transform.TransformPoint(hip.connectedAnchor);ball.position=at+new Vector2((isFan?1:-1)*.28f*scale,.35f*scale);ball.velocity=Vector2.zero;Physics2D.SyncTransforms();Action(a,"Kick");int boosted=SkillRework.ShootingLevel(a);AbilityMode.For(a).Levels[0]=8;Check(boosted==5&&SkillRework.ShootingLevel(a)==8,"magnetic aerial command adds shot point capped at eight actor="+a.name+" boosted="+boosted);}
 IEnumerator Range(){yield return Scene(12);Setup(fan);AbilityMode.For(fan).Purchased=1<<10;var s=fan.GetComponent<SkillRework>();var range=typeof(SkillRework).GetMethod("BicycleRange",IP);var h=fan.transform.Find("Head").GetComponent<Collider2D>();float x=Body(fan).position.x-.4f*scale;ball.position=new Vector2(x,Body(fan).position.y-.1f*scale);bool below=!(bool)range.Invoke(s,null);ball.position=new Vector2(x,h.bounds.max.y+h.bounds.size.y+.02f*scale);bool above=!(bool)range.Invoke(s,null);ball.position=new Vector2(x,Body(fan).position.y+.1f*scale);bool valid=(bool)range.Invoke(s,null);int before=bicycles;SeedSuccess();Action(fan,"Kick");Check(below&&above&&valid&&bicycles==before,"current torso/head bounds and jump requirement");}
 IEnumerator Rescue(){yield return Scene(12);Setup(zhao);AbilityMode.For(zhao).Purchased=1<<6;ball.position=Body(zhao).position+new Vector2(1.8f*scale,-.8f*scale);ball.velocity=new Vector2(12f,0);ball.gravityScale=1;Physics2D.SyncTransforms();var owner=zhao.GetComponent<BuildPlayer>();for(int i=0;i<4;i++)owner.RescueAxis(1);float actual=(float)typeof(BuildPlayer).GetField("rescueSpeed",IP).GetValue(owner),normal=(float)pt.GetField("maxVelocity").GetValue(zhao)*PlayerMovement.BackwardMultiplier;Check(actual<=normal*2f+.01f,"allocated emergency rescue stays below 200 percent actual="+actual+" cap="+(normal*2));}
 IEnumerator Dribble(bool isFan){yield return Scene(12,isFan?1:2);var a=isFan?fan:zhao;Setup(a);if(!isFan)AbilityMode.For(a).Purchased=1;ball.position=new Vector2(Body(a).position.x+(isFan?1:-1)*.7f*scale,floorLimit+ball.GetComponent<Collider2D>().bounds.extents.y);ball.velocity=Vector2.zero;ball.gravityScale=1;Physics2D.SyncTransforms();for(int i=0;i<4;i++)yield return new WaitForFixedUpdate();float m=isFan?PlayerSkills.GetMovementSkillMultiplier(a,1):AbilityMode.Movement(a,-1);Check(Mathf.Abs(m-1.4f)<.01f,"whirlwind advances at plus 40 percent actor="+a.name+" multiplier="+m);}
 IEnumerator OrdinaryPower(int mode){yield return Scene(12,mode,false);Setup(zhao);ball.position=Body(zhao).position+new Vector2(-.6f*scale,-.5f*scale);ball.velocity=new Vector2(-6f,3f);ball.gravityScale=1;Physics2D.SyncTransforms();var shot=zhao.GetComponent<PowerShot>();PowerShot.Request(zhao);Action(zhao,"Kick");yield return null;float until=(float)typeof(PowerShot).GetField("flatUntil",IP).GetValue(shot);Check(until<0&&!AbilityMode.For(zhao).Has(4),"ordinary Zhao power kick has no ground-skimming guidance mode="+mode);}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);if(MotionOnly){foreach(bool side in new bool[]{true,false}){yield return Motion(side,.7f,.4f);yield return Motion(side,1.2f,.45f);yield return Motion(side,.2f,.4f);}Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);yield break;}Rules();yield return Preview(true);yield return Preview(false);yield return Dribble(true);yield return Dribble(false);foreach(int mode in new int[]{0,1,2})yield return OrdinaryPower(mode);yield return Range();yield return Rescue();foreach(bool side in new bool[]{true,false}){yield return Passives(side);yield return Knocked(side);yield return Magnetic(side);yield return Fallback(side,0);yield return Fallback(side,1);foreach(bool rear in new bool[]{false,true})yield return Header(side,2,false,rear);yield return Header(side,2,true,false);}yield return Header(true,1,true,false);Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
 void Update(){if(Time.realtimeSinceStartup>140){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
